import { cache as reactCache } from "react";
import { prisma } from "@formbricks/database";

export const getIsEmailUnique = reactCache(async (email: string): Promise<boolean> => {
  const user = await prisma.user.findUnique({
    where: {
      email: email.toLowerCase(),
    },
    select: {
      id: true,
    },
  });

  return !user;
});

"use server";

import { headers } from "next/headers";
import {
  AuthenticationError,
  AuthorizationError,
  OperationNotAllowedError,
  TooManyRequestsError,
} from "@formbricks/types/errors";
import {
  TUserPersonalInfoUpdateInput,
  TUserUpdateInput,
  ZUserPersonalInfoUpdateInput,
} from "@formbricks/types/user";
import { getIsEmailUnique } from "@/app/(app)/workspaces/[workspaceId]/settings/account/profile/lib/user";
import { EMAIL_VERIFICATION_DISABLED, PASSWORD_RESET_DISABLED, WEBAPP_URL } from "@/lib/constants";
import { verifyUserPassword } from "@/lib/user/password";
import { getUser, updateUser } from "@/lib/user/service";
import { authenticatedActionClient } from "@/lib/utils/action-client";
import { AuthenticatedActionClientCtx } from "@/lib/utils/action-client/types/context";
import { auth } from "@/modules/auth/lib/auth";
import { updateBrevoCustomer } from "@/modules/auth/lib/brevo";
import { applyRateLimit } from "@/modules/core/rate-limit/helpers";
import { rateLimitConfigs } from "@/modules/core/rate-limit/rate-limit-configs";
import { withAuditLogging } from "@/modules/ee/audit-logs/lib/handler";
import { sendVerificationNewEmail } from "@/modules/email";

function buildUserUpdatePayload(parsedInput: TUserPersonalInfoUpdateInput): TUserUpdateInput {
  return {
    ...(parsedInput.name && { name: parsedInput.name }),
    ...(parsedInput.locale && { locale: parsedInput.locale }),
  };
}

/**
 * Refuse a name change for an SSO user, mirroring the identical guard `handleEmailUpdate` applies to
 * the address.
 *
 * The identity provider owns `User.name` — it is re-read on every sign-in (`overrideUserInfo` in
 * modules/ee/sso/lib/better-auth-providers.ts) — so `EditProfileDetailsForm` renders the input
 * disabled. That is presentation, not enforcement: this action takes `name` straight off the request,
 * so a crafted call would still land a write that sticks until the user's next sign-in silently
 * reverts it. Enforce it at the boundary instead.
 *
 * Only a *differing* name is rejected. The form omits untouched fields, but a client that echoes the
 * current value back is asking for no change, and erroring on that would be a false positive.
 */
function assertNameUpdateAllowed({
  ctx,
  parsedInput,
}: {
  ctx: AuthenticatedActionClientCtx;
  parsedInput: TUserPersonalInfoUpdateInput;
}): void {
  const inputName = parsedInput.name?.trim();
  if (!inputName || inputName === ctx.user.name) return;

  if (ctx.user.identityProvider !== "email") {
    throw new OperationNotAllowedError("Name update is not allowed for non-credential users.");
  }
}

async function handleEmailUpdate({
  ctx,
  parsedInput,
  payload,
}: {
  ctx: AuthenticatedActionClientCtx;
  parsedInput: TUserPersonalInfoUpdateInput;
  payload: TUserUpdateInput;
}) {
  const inputEmail = parsedInput.email?.trim().toLowerCase();
  if (!inputEmail || ctx.user.email === inputEmail) return payload;

  await applyRateLimit(rateLimitConfigs.actions.emailUpdate, ctx.user.id);

  if (ctx.user.identityProvider !== "email") {
    throw new OperationNotAllowedError("Email update is not allowed for non-credential users.");
  }
  if (!parsedInput.password) {
    throw new AuthenticationError("Password is required to update email.");
  }
  const isCorrectPassword = await verifyUserPassword(ctx.user.id, parsedInput.password);
  if (!isCorrectPassword) {
    throw new AuthorizationError("Incorrect credentials");
  }
  const isEmailUnique = await getIsEmailUnique(inputEmail);
  if (!isEmailUnique) return payload;

  if (EMAIL_VERIFICATION_DISABLED) {
    payload.email = inputEmail;
    await updateBrevoCustomer({ id: ctx.user.id, email: inputEmail });
  } else {
    try {
      await sendVerificationNewEmail(ctx.user.id, inputEmail, ctx.user.locale);
    } catch (error) {
      // A taken address returns quietly above, so a capped email (ENG-3823) must too, or the refusal would
      // tell the user which addresses are free.
      if (!(error instanceof TooManyRequestsError)) throw error;
    }
  }
  return payload;
}

export const updateUserAction = authenticatedActionClient.inputSchema(ZUserPersonalInfoUpdateInput).action(
  withAuditLogging("updated", "user", async ({ ctx, parsedInput }) => {
    const oldObject = await getUser(ctx.user.id);
    assertNameUpdateAllowed({ ctx, parsedInput });
    let payload = buildUserUpdatePayload(parsedInput);
    payload = await handleEmailUpdate({ ctx, parsedInput, payload });

    // Only proceed with updateUser if we have actual changes to make
    let newObject = oldObject;
    if (Object.keys(payload).length > 0) {
      newObject = await updateUser(ctx.user.id, payload);
    }

    ctx.auditLoggingCtx.userId = ctx.user.id;
    ctx.auditLoggingCtx.oldObject = oldObject;
    ctx.auditLoggingCtx.newObject = newObject;

    return true;
  })
);

export const resetPasswordAction = authenticatedActionClient.action(
  withAuditLogging("passwordReset", "user", async ({ ctx }) => {
    if (PASSWORD_RESET_DISABLED) {
      throw new OperationNotAllowedError("Password reset is disabled");
    }

    if (ctx.user.identityProvider !== "email") {
      throw new OperationNotAllowedError("Password reset is not allowed for this user.");
    }

    // Without a limit this was the one way to have reset emails sent unbounded. A budget of its own, so
    // strangers spending forgot-password's per-account budget cannot lock the user out of this one.
    await applyRateLimit(rateLimitConfigs.actions.passwordResetRequest, ctx.user.id);

    await auth.api.requestPasswordReset({
      body: { email: ctx.user.email, redirectTo: `${WEBAPP_URL}/auth/forgot-password/reset` },
      headers: await headers(),
    });

    ctx.auditLoggingCtx.userId = ctx.user.id;

    return { success: true };
  })
);

"use client";

import { useState } from "react";
import { useTranslation } from "react-i18next";
import { TUser } from "@formbricks/types/user";
import { DisableTwoFactorModal } from "@/modules/ee/two-factor-auth/components/disable-two-factor-modal";
import { EnableTwoFactorModal } from "@/modules/ee/two-factor-auth/components/enable-two-factor-modal";
import { Switch } from "@/modules/ui/components/switch";

interface AccountSecurityProps {
  user: TUser;
}

export const AccountSecurity = ({ user }: AccountSecurityProps) => {
  const { t } = useTranslation();
  const [twoFactorModalOpen, setTwoFactorModalOpen] = useState(false);
  const [disableTwoFactorModalOpen, setDisableTwoFactorModalOpen] = useState(false);

  return (
    <div>
      <div className="flex items-center gap-x-4">
        <Switch
          checked={user.twoFactorEnabled}
          onCheckedChange={(checked) => {
            if (checked) {
              setTwoFactorModalOpen(true);
            } else {
              setDisableTwoFactorModalOpen(true);
            }
          }}
        />
        <div className="flex flex-col">
          <h1 className="text-sm font-semibold text-slate-800">
            {t("workspace.settings.profile.two_factor_authentication")}
          </h1>

          <p className="text-xs text-slate-600">
            {t("workspace.settings.profile.two_factor_authentication_description")}
          </p>
        </div>
      </div>
      <EnableTwoFactorModal open={twoFactorModalOpen} setOpen={setTwoFactorModalOpen} />
      <DisableTwoFactorModal open={disableTwoFactorModalOpen} setOpen={setDisableTwoFactorModalOpen} />
    </div>
  );
};

"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { ChevronDownIcon } from "lucide-react";
import { useState } from "react";
import { FormProvider, SubmitHandler, useForm } from "react-hook-form";
import toast from "react-hot-toast";
import { useTranslation } from "react-i18next";
import { z } from "zod";
import { TUser, TUserUpdateInput, ZUser, ZUserEmail } from "@formbricks/types/user";
import { PasswordConfirmationModal } from "@/app/(app)/workspaces/[workspaceId]/settings/account/profile/components/password-confirmation-modal";
import { appLanguages, sortedAppLanguages } from "@/lib/i18n/utils";
import { getFormattedErrorMessage } from "@/lib/utils/error-message";
import { useSignOut } from "@/modules/auth/hooks/use-sign-out";
import { Button } from "@/modules/ui/components/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/modules/ui/components/dropdown-menu";
import { FormControl, FormError, FormField, FormItem, FormLabel } from "@/modules/ui/components/form";
import { Input } from "@/modules/ui/components/input";
import { Label } from "@/modules/ui/components/label";
import { resetPasswordAction, updateUserAction } from "../actions";

// Schema & types
const ZEditProfileNameFormSchema = ZUser.pick({ name: true, locale: true, email: true }).extend({
  email: ZUserEmail.transform((val) => val?.trim().toLowerCase()),
});
type TEditProfileNameForm = z.infer<typeof ZEditProfileNameFormSchema>;

interface IEditProfileDetailsFormProps {
  user: TUser;
  isPasswordResetEnabled?: boolean;
  emailVerificationDisabled: boolean;
}

export const EditProfileDetailsForm = ({
  user,
  isPasswordResetEnabled,
  emailVerificationDisabled,
}: IEditProfileDetailsFormProps) => {
  const { t } = useTranslation();

  const form = useForm<TEditProfileNameForm>({
    defaultValues: {
      name: user.name,
      locale: user.locale,
      email: user.email,
    },
    mode: "onChange",
    resolver: zodResolver(ZEditProfileNameFormSchema),
  });

  const { isSubmitting, isDirty } = form.formState;

  const [isResettingPassword, setIsResettingPassword] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const { signOut: signOutWithAudit } = useSignOut({ id: user.id, email: user.email });

  const handleConfirmPassword = async (password: string) => {
    const values = form.getValues();
    const dirtyFields = form.formState.dirtyFields;

    const emailChanged = "email" in dirtyFields;
    const nameChanged = "name" in dirtyFields;
    const localeChanged = "locale" in dirtyFields;

    const name = values.name.trim();
    const email = values.email.trim().toLowerCase();
    const locale = values.locale;

    const data: TUserUpdateInput = {};

    if (emailChanged) {
      data.email = email;
      data.password = password;
    }
    if (nameChanged) {
      data.name = name;
    }
    if (localeChanged) {
      data.locale = locale;
    }

    const updatedUserResult = await updateUserAction(data);

    if (updatedUserResult?.data) {
      if (!emailVerificationDisabled) {
        toast.success(t("auth.verification-requested.new_email_verification_success"));
      } else {
        toast.success(t("workspace.settings.profile.email_change_initiated"));
        await signOutWithAudit({
          reason: "email_change",
          redirectUrl: "/email-change-without-verification-success",
          redirect: true,
          callbackUrl: "/email-change-without-verification-success",
          clearWorkspaceId: true,
        });
        return;
      }
    } else {
      const errorMessage = getFormattedErrorMessage(updatedUserResult);
      toast.error(errorMessage);
      return;
    }

    window.location.reload();
    setShowModal(false);
  };

  const onSubmit: SubmitHandler<TEditProfileNameForm> = async (data) => {
    if (data.email !== user.email) {
      setShowModal(true);
    } else {
      try {
        const result = await updateUserAction({
          ...data,
          name: data.name.trim(),
        });
        if (result?.serverError) {
          toast.error(getFormattedErrorMessage(result));
          return;
        }
        toast.success(t("workspace.settings.profile.profile_updated_successfully"));
        window.location.reload();
        form.reset(data);
      } catch (error: any) {
        toast.error(`${t("common.error")}: ${error.message}`);
      }
    }
  };

  const handleResetPassword = async () => {
    setIsResettingPassword(true);

    const result = await resetPasswordAction();
    if (result?.data) {
      toast.success(t("auth.forgot-password.email-sent.heading"));

      await signOutWithAudit({
        reason: "password_reset",
        redirectUrl: "/auth/login",
        redirect: true,
        callbackUrl: "/auth/login",
        clearWorkspaceId: true,
      });
    } else {
      const errorMessage = getFormattedErrorMessage(result);
      toast.error(errorMessage);
    }

    setIsResettingPassword(false);
  };

  return (
    <>
      <FormProvider {...form}>
        <form className="w-full max-w-sm" onSubmit={form.handleSubmit(onSubmit)}>
          <FormField
            control={form.control}
            name="name"
            render={({ field }) => (
              <FormItem>
                <FormLabel>{t("common.full_name")}</FormLabel>
                <FormControl>
                  <Input
                    {...field}
                    type="text"
                    required
                    placeholder={t("common.full_name")}
                    isInvalid={!!form.formState.errors.name}
                    // The identity provider owns an SSO user's name: it is re-read on every sign-in
                    // (`overrideUserInfo` in modules/ee/sso/lib/better-auth-providers.ts), so an edit
                    // here would be silently reverted at their next login. Same treatment, and the
                    // same condition, as the email field below.
                    disabled={user.identityProvider !== "email"}
                  />
                </FormControl>
                <FormError />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="email"
            render={({ field }) => (
              <FormItem className="mt-4">
                <FormLabel>{t("common.email")}</FormLabel>
                <FormControl>
                  <Input
                    {...field}
                    type="email"
                    required
                    isInvalid={!!form.formState.errors.email}
                    disabled={user.identityProvider !== "email"}
                  />
                </FormControl>
                <FormError />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="locale"
            render={({ field }) => {
              const selectedLanguage = appLanguages.find((l) => l.code === field.value);

              return (
                <FormItem className="mt-4">
                  <FormLabel>{t("common.language")}</FormLabel>
                  <FormControl>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          type="button"
                          variant="ghost"
                          className="h-10 w-full border border-slate-300 px-3 text-left">
                          <div className="flex w-full items-center justify-between">
                            {selectedLanguage ? (
                              <>
                                {selectedLanguage.label["en-US"]}
                                {selectedLanguage.label.native !== selectedLanguage.label["en-US"] &&
                                  ` (${selectedLanguage.label.native})`}
                              </>
                            ) : (
                              t("common.select")
                            )}
                            <ChevronDownIcon className="size-4 text-slate-500" />
                          </div>
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent
                        className="min-w-(--radix-dropdown-menu-trigger-width) bg-white text-slate-700"
                        align="start">
                        <DropdownMenuRadioGroup value={field.value} onValueChange={field.onChange}>
                          {sortedAppLanguages.map((lang) => (
                            <DropdownMenuRadioItem
                              key={lang.code}
                              value={lang.code}
                              className="min-h-8 cursor-pointer">
                              {lang.label["en-US"]}
                              {lang.label.native !== lang.label["en-US"] && ` (${lang.label.native})`}
                            </DropdownMenuRadioItem>
                          ))}
                        </DropdownMenuRadioGroup>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </FormControl>
                  <FormError />
                </FormItem>
              );
            }}
          />

          {isPasswordResetEnabled && (
            <div className="mt-4 space-y-2">
              <Label htmlFor="reset-password">{t("auth.forgot-password.reset_password")}</Label>
              <p className="mt-1 text-sm text-slate-500">
                {t("auth.forgot-password.reset_password_description")}
              </p>
              <div className="flex items-center justify-between gap-2">
                <Input type="email" id="reset-password" defaultValue={user.email} disabled />
                <Button
                  onClick={handleResetPassword}
                  loading={isResettingPassword}
                  disabled={isResettingPassword}
                  size="default"
                  variant="secondary">
                  {t("auth.forgot-password.reset_password")}
                </Button>
              </div>
            </div>
          )}

          <Button
            type="submit"
            className="mt-4"
            size="sm"
            loading={isSubmitting}
            disabled={isSubmitting || !isDirty}>
            {t("common.update")}
          </Button>
        </form>
      </FormProvider>

      <PasswordConfirmationModal
        open={showModal}
        setOpen={setShowModal}
        oldEmail={user.email}
        newEmail={form.getValues("email") || user.email}
        onConfirm={handleConfirmPassword}
      />
    </>
  );
};

const SettingsLayout = (props: { children: React.ReactNode }) => {
  return <>{props.children}</>;
};

export default SettingsLayout;

"use client";

import { useTranslation } from "react-i18next";
import { LoadingCard } from "@/app/(app)/components/LoadingCard";
import { PageContentWrapper } from "@/modules/ui/components/page-content-wrapper";
import { PageHeader } from "@/modules/ui/components/page-header";

const Loading = () => {
  const { t } = useTranslation();
  const cards = [
    {
      title: t("workspace.settings.profile.personal_information"),
      description: t("workspace.settings.profile.update_personal_info"),
      skeletonLines: [
        { classes: "h-4 w-28" },
        { classes: "h-6 w-64" },
        { classes: "h-4 w-28" },
        { classes: "h-6 w-64" },
      ],
    },
    {
      title: t("workspace.settings.profile.delete_account"),
      description: t("workspace.settings.profile.confirm_delete_account"),
      skeletonLines: [{ classes: "h-4 w-60" }, { classes: "h-8 w-24" }],
    },
