interface AccountActivityProps {
  user: TUser;
}

export const AccountActivity = ({ user }: AccountActivityProps) => {
  const { t } = useTranslation();

  const formatDate = (date: Date | null): string => {
    if (!date) return t("common.not_available");
    return formatDateTimeForDisplay(date, user.locale);
  };

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <span className="text-sm text-slate-600">
          {t("workspace.settings.profile.account_created")}
        </span>
        <span className="text-sm font-medium text-slate-800">
          {formatDate(user.createdAt)}
        </span>
      </div>
      <div className="flex items-center justify-between">
        <span className="text-sm text-slate-600">
          {t("workspace.settings.profile.last_login")}
        </span>
        <span className="text-sm font-medium text-slate-800">
          {formatDate(user.lastLoginAt)}
        </span>
      </div>
    </div>
  );
};

